mapper.select:
/* com.heeji.picket.mapper.ShowsMapper.list */ SELECT S.SHOW_ID AS showId , S.TITLE AS title , S.PLACE AS place , S.PLACE_ADDRESS AS placeAddress , S.GENRE AS genre , S.HOST AS host , S.CONTACT AS contact , S.AGE_LIMIT AS ageLimit , S.OPEN_DATE AS openDate , S.IS_DELETED AS isDeleted , S.INFO AS info , S.POSTER_LINK AS posterLink , S.INSERT_DATE AS insertDate , S.INSERT_ID AS insertId , S.UPDATE_DATE AS updateDate , S.UPDATE_ID AS updateId , (SELECT MIN(SG.PRICE) FROM SEAT_GRADE SG WHERE SG.SHOW_ID = S.SHOW_ID) AS minPrice , ( SELECT COUNT(*) FROM SEAT SE WHERE SE.SHOW_ID = S.SHOW_ID AND IFNULL(SE.SEAT_STATUS, 'available') = 'available' ) AS remainCount , (SELECT MIN(SD.SHOW_DATE) FROM SHOW_DATE SD WHERE SD.SHOW_ID = S.SHOW_ID) AS startDate , (SELECT MAX(SD.SHOW_DATE) FROM SHOW_DATE SD WHERE SD.SHOW_ID = S.SHOW_ID) AS endDate , ( SELECT COUNT(*) FROM SEAT SE WHERE SE.SHOW_ID = S.SHOW_ID AND SE.SEAT_STATUS = 'booked' ) AS bookedCount , (SELECT COUNT(*) FROM SHOW_LIKES L WHERE L.SHOW_ID = S.SHOW_ID) AS likeCount FROM SHOWS S WHERE S.IS_DELETED IS NULL
AND S.GENRE = #{genre}
ORDER BY likeCount DESC, bookedCount DESC, S.SHOW_ID DESC
ORDER BY bookedCount DESC, likeCount DESC, S.SHOW_ID DESC
ORDER BY S.SHOW_ID DESC
LIMIT #{size} OFFSET #{offset}

/* com.heeji.picket.mapper.ShowsMapper.count */
SELECT  COUNT(*)
FROM    SHOWS S
WHERE   S.IS_DELETED IS NULL

AND     S.GENRE = #{genre}

/* com.heeji.picket.mapper.ShowsMapper.mineCount */
SELECT  COUNT(*)
FROM    SHOWS S
WHERE   S.IS_DELETED IS NULL
AND     S.INSERT_ID = #{userId}

mapper.update:
/* com.heeji.picket.mapper.ShowsMapper.update */
UPDATE  SHOWS
SET     TITLE       = #{title}
,       GENRE       = #{genre}
,       PLACE         = #{place}
,       PLACE_ADDRESS = #{placeAddress}
,       HOST          = #{host}
,       CONTACT     = #{contact}
,       AGE_LIMIT   = #{ageLimit}
,       POSTER_LINK = #{posterLink}
,       INFO        = #{info}
,       OPEN_DATE   = #{openDate}
,       UPDATE_DATE = NOW()
,       UPDATE_ID   = #{loginId}
WHERE   SHOW_ID = #{showId}
AND     INSERT_ID = #{loginId}
AND     IS_DELETED IS NULL

/* com.heeji.picket.mapper.ShowsMapper.softDelete */
UPDATE  SHOWS
SET     IS_DELETED  = NOW()
,       UPDATE_DATE = NOW()
,       UPDATE_ID   = #{loginId}
WHERE   SHOW_ID = #{showId}
AND     INSERT_ID = #{loginId}
AND     IS_DELETED IS NULL
